import java.util.*;
public class ServiceTest { static void eq(Object actual,Object expected){if(!Objects.equals(actual,expected))throw new AssertionError("expected="+expected+" actual="+actual);}static void yes(boolean value){if(!value)throw new AssertionError("contract violated");}public static void main(String[]args)throws Exception{
var closed=new java.util.concurrent.atomic.AtomicInteger();eq(Service.load(new Service.Handle(){public String read(){return "ok";}public void close(){closed.incrementAndGet();}}),"ok");eq(closed.get(),1);var primary=new Exception("read");var secondary=new Exception("close");try{Service.load(new Service.Handle(){public String read()throws Exception{throw primary;}public void close()throws Exception{closed.incrementAndGet();throw secondary;}});throw new AssertionError();}catch(Exception e){eq(e,primary);eq(e.getSuppressed().length,1);eq(e.getSuppressed()[0],secondary);}eq(closed.get(),2);
System.out.println("PASS business-resource-suppression");}}
